import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    W = int(next(it))
    H = int(next(it))
    N = int(next(it))
    devices = []
    for _ in range(N):
        x = int(next(it))
        y = int(next(it))
        devices.append((x, y))

    # Precompute prefix sums for rows and columns
    row_prefix = [[0] * (H + 1) for _ in range(W + 1)]
    col_prefix = [[0] * (W + 1) for _ in range(H + 1)]

    for i in range(1, W + 1):
        for j in range(1, H + 1):
            row_prefix[i][j] = row_prefix[i][j - 1] + (1 if (i, j) in devices else 0)
            col_prefix[i][j] = col_prefix[i - 1][j] + (1 if (i, j) in devices else 0)

    def count_nuggets(x1, y1, x2, y2):
        if x1 > x2 or y1 > y2:
            return 0
        return row_prefix[x2][y2] - row_prefix[x1 - 1][y2] - row_prefix[x2][y1 - 1] + row_prefix[x1 - 1][y1 - 1]

    def count_nuggets_row(x, y, direction):
        if direction == 'east':
            p = x + 1
            while p <= W and (p, y) not in devices:
                p += 1
            return count_nuggets(x + 1, y, p - 1, y)
        elif direction == 'west':
            p = x - 1
            while p >= 1 and (p, y) not in devices:
                p -= 1
            return count_nuggets(p + 1, y, x - 1, y)
        elif direction == 'south':
            q = y + 1
            while q <= H and (x, q) not in devices:
                q += 1
            return count_nuggets(x, y + 1, x, q - 1)
        elif direction == 'north':
            q = y - 1
            while q >= 1 and (x, q) not in devices:
                q -= 1
            return count_nuggets(x, q + 1, x, y - 1)

    def count_nuggets_col(x, y, direction):
        if direction == 'east':
            q = y + 1
            while q <= H and (x, q) not in devices:
                q += 1
            return count_nuggets(x, y + 1, x, q - 1)
        elif direction == 'west':
            q = y - 1
            while q >= 1 and (x, q) not in devices:
                q -= 1
            return count_nuggets(x, q + 1, x, y - 1)
        elif direction == 'south':
            p = x + 1
            while p <= W and (p, y) not in devices:
                p += 1
            return count_nuggets(p, y, x - 1, y)
        elif direction == 'north':
            p = x - 1
            while p >= 1 and (p, y) not in devices:
                p -= 1
            return count_nuggets(p + 1, y, x - 1, y)

    def count_nuggets_device(x, y):
        total = 1
